3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	
14	import java.time.LocalDate;
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public abstract class OwnerMapper {
23	
24	    /**
25	     * More than this many owners already sharing a {@code registrationDate} raises the
26	     * {@code bulkSignupWarning} on responses for that day.
27	     */
28	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
29	
30	    @Autowired
31	    protected OwnerRepository ownerRepository;
32	
33	    @Mapping(target = "displayName",
34	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
35	    @Mapping(target = "initials",
36	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
37	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
38	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
39	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
40	    @Mapping(target = "locality", expression = "java(locality(owner))")
41	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
42	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
43	    @Mapping(target = "identityKey",
44	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner))")
45	    public abstract OwnerDto toOwnerDto(Owner owner);
46	
47	    /**
48	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
49	     * present (non-null and non-blank), otherwise {@code PHONE}.
50	     */
51	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
52	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
53	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
54	    }
55	
56	    /**
57	     * Derives the owner's {@code locality} (canonical region string) from the
58	     * region-and-hash identity: the REGION segment of the {@code customerCode} (everything
59	     * before the first {@code '-'}). Legacy owners with no customer code (e.g. seed data)
60	     * fall back to deriving the region directly from postcode, then city, then
61	     * {@code "UNKNOWN"}.
62	     */
63	    protected String locality(Owner owner) {
64	        String region = org.springframework.samples.petclinic.rest.function.owner.CustomerCodes
65	                .regionOf(owner.getCustomerCode());
66	        if (region != null) {
67	            return region;
68	        }
69	        return org.springframework.samples.petclinic.rest.function.owner.CustomerCodes.region(owner);
70	    }
71	
72	    /**
73	     * The membership level is capped at this value; level 4 is reserved for tenure.
74	     */
75	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
76	
77	    /**
78	     * Returns the owner's membership level, a number from 1 to
79	     * {@value #MAX_MEMBERSHIP_LEVEL} assigned at creation: it starts at 1, gains 1 when
80	     * an email address is present, gains 1 when the owner has no namesakes
81	     * (namesakeCount is 0), and is capped at {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is
82	     * reserved for tenure).
83	     */
84	    public static int membershipLevel(Owner owner) {
85	        int level = 1;
86	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
87	        if (hasEmail) {
88	            level++;
89	        }
90	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
91	        if (noNamesakes) {
92	            level++;
93	        }
94	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
95	    }
96	
97	    /**
98	     * Builds the membership number '<customerCode>-M<YY>', where YY is the last two digits of
99	     * the registrationDate year (e.g. 'NSW-1A2B3C4D-M26'). Returns {@code null} when either the
100	     * customer code or the registration date is absent (e.g. legacy seed owners).
101	     */
102	    protected String membershipNumber(Owner owner) {
103	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
104	            return null;
105	        }
106	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
107	    }
108	
109	    /**
110	     * True when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} other owners have already
111	     * been created for this owner's {@code registrationDate}, using the same per-day
112	     * accumulation the daily create limit enforces (the owner itself is excluded). Returns
113	     * {@code false} when the owner has no registration date (e.g. legacy seed owners).
114	     */
115	    protected boolean bulkSignupWarning(Owner owner) {
116	        LocalDate registrationDate = owner.getRegistrationDate();
117	        if (registrationDate == null) {
118	            return false;
119	        }
120	        long count = ownerRepository.findAll().stream()
121	                .filter(existing -> !existing.getId().equals(owner.getId()))
122	                .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
123	                .count();
124	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
125	    }
